    78	    videoAspectRatio: videoAspectRatioProp,
    79	    title = '',
    80	    description = '',
    81	    secondaryDescription = '',
    82	    shouldShowDismissModalOption = false,
    83	    confirmText = '',
    84	    onConfirm = () => {},
    85	    onClose = () => {},
    86	    helpText = '',
    87	    onHelp = () => {},
    88	}: FeatureTrainingModalProps) {
    89	    const styles = useThemeStyles();
    90	    const {translate} = useLocalize();
    91	    const {onboardingIsMediumOrLargerScreenWidth} = useResponsiveLayout();
    92	    const [isModalVisible, setIsModalVisible] = useState(true);
    93	    const [willShowAgain, setWillShowAgain] = useState(true);
    94	    const [videoStatus, setVideoStatus] = useState<VideoStatus>('video');
    95	    const [isVideoStatusLocked, setIsVideoStatusLocked] = useState(false);
    96	    const [videoAspectRatio, setVideoAspectRatio] = useState(videoAspectRatioProp ?? VIDEO_ASPECT_RATIO);
    97	    const {shouldUseNarrowLayout} = useResponsiveLayout();
    98	    const {isOffline} = useNetwork();
    99	
   100	    useEffect(() => {
   101	        if (isVideoStatusLocked) {
   102	            return;
   103	        }
   104	
   105	        if (isOffline) {
   106	            setVideoStatus('animation');
   107	        } else if (!isOffline) {
   108	            setVideoStatus('video');
   109	            setIsVideoStatusLocked(true);
   110	        }
   111	    }, [isOffline, isVideoStatusLocked]);
   112	
   113	    const setAspectRatio = (event: VideoReadyForDisplayEvent | VideoLoadedEventType | undefined) => {
   114	        if (!event) {
   115	            return;
   116	        }
   117	
   118	        if ('naturalSize' in event) {
   119	            setVideoAspectRatio(event.naturalSize.width / event.naturalSize.height);
   120	        } else {
   121	            setVideoAspectRatio(event.srcElement.videoWidth / event.srcElement.videoHeight);
   122	        }
