   156	                            webStyle={shouldUseNarrowLayout ? styles.h100 : undefined}
   157	                            autoPlay
   158	                            loop
   159	                        />
   160	                    </View>
   161	                )}
   162	            </View>
   163	        );
   164	    }, [animation, videoURL, videoAspectRatio, videoStatus, shouldUseNarrowLayout, styles]);
   165	
   166	    const toggleWillShowAgain = useCallback(() => setWillShowAgain((prevWillShowAgain) => !prevWillShowAgain), []);
   167	
   168	    const closeModal = useCallback(() => {
   169	        if (!willShowAgain) {
   170	            User.dismissTrackTrainingModal();
   171	        }
   172	        setIsModalVisible(false);
   173	        Navigation.goBack();
   174	        onClose?.();
   175	    }, [onClose, willShowAgain]);
   176	
   177	    const closeAndConfirmModal = useCallback(() => {
   178	        closeModal();
   179	        onConfirm?.();
   180	    }, [onConfirm, closeModal]);
   181	
   182	    return (
   183	        <SafeAreaConsumer>
