   191	                        borderRadius: 16,
   192	                        paddingBottom: 20,
   193	                        paddingTop: onboardingIsMediumOrLargerScreenWidth ? undefined : MODAL_PADDING,
   194	                        ...(onboardingIsMediumOrLargerScreenWidth
   195	                            ? // Override styles defined by MODAL.MODAL_TYPE.CENTERED_UNSWIPEABLE
   196	                              // To make it take as little space as possible.
   197	                              {
   198	                                  flex: undefined,
   199	                                  width: 'auto',
   200	                              }
   201	                            : {}),
   202	                    }}
   203	                >
   204	                    <View style={[styles.mh100, onboardingIsMediumOrLargerScreenWidth && styles.welcomeVideoNarrowLayout, safeAreaPaddingBottomStyle]}>
   205	                        <View style={onboardingIsMediumOrLargerScreenWidth ? {padding: MODAL_PADDING} : {paddingHorizontal: MODAL_PADDING}}>{renderIllustration()}</View>
   206	                        <View style={[styles.mt5, styles.mh5]}>
   207	                            {!!title && !!description && (
   208	                                <View style={[onboardingIsMediumOrLargerScreenWidth ? [styles.gap1, styles.mb8] : [styles.mb10]]}>
   209	                                    <Text style={[styles.textHeadlineH1]}>{title}</Text>
   210	                                    <Text style={styles.textSupporting}>{description}</Text>
   211	                                    {secondaryDescription.length > 0 && <Text style={[styles.textSupporting, styles.mt4]}>{secondaryDescription}</Text>}
   212	                                </View>
   213	                            )}
   214	                            {shouldShowDismissModalOption && (
   215	                                <CheckboxWithLabel
   216	                                    label={translate('featureTraining.doNotShowAgain')}
   217	                                    accessibilityLabel={translate('featureTraining.doNotShowAgain')}
   218	                                    style={[styles.mb5]}
   219	                                    isChecked={!willShowAgain}
   220	                                    onInputChange={toggleWillShowAgain}
   221	                                />
   222	                            )}
   223	                            {!!helpText && (
   224	                                <Button
   225	                                    large
   226	                                    style={[styles.mb3]}
   227	                                    onPress={onHelp}
   228	                                    text={helpText}
   229	                                />
   230	                            )}
   231	                            <Button
   232	                                large
   233	                                success
   234	                                pressOnEnter
   235	                                onPress={closeAndConfirmModal}
   236	                                text={confirmText}
   237	                            />
   238	                        </View>
   239	                    </View>
   240	                </Modal>
   241	            )}
   242	        </SafeAreaConsumer>
