    51	        // But, we still want the requestee to be able to put the request on hold
    52	        if (ReportActionsUtils.isMoneyRequestAction(parentReportAction) && !ReportUtils.canEditMoneyRequest(parentReportAction) && isWorkspaceRequest) {
    53	            return;
