    62	            const errors: FormInputErrors<typeof ONYXKEYS.FORMS.MONEY_REQUEST_HOLD_FORM> = ValidationUtils.getFieldRequiredErrors(values, [INPUT_IDS.COMMENT]);
    63	
    64	            if (!values.comment) {
    65	                errors.comment = translate('common.error.fieldRequired');
    66	            }
    67	            // We have extra isWorkspaceRequest condition since, for 1:1 requests, canEditMoneyRequest will rightly return false
    68	            // as we do not allow requestee to edit fields like description and amount.
    69	            // But, we still want the requestee to be able to put the request on hold
    70	            if (ReportActionsUtils.isMoneyRequestAction(parentReportAction) && !ReportUtils.canEditMoneyRequest(parentReportAction) && isWorkspaceRequest) {
